/**
 * Options for constructing a {@link PromptLayer} client.
 *
 * Prefer the published JavaScript SDK docs over inspecting bundled internals:
 * https://docs.promptlayer.com/sdks/javascript
 *
 * @see https://docs.promptlayer.com/sdks/javascript
 * @see https://docs.promptlayer.com/llms.txt
 */
export interface ClientOptions {
  /** PromptLayer API key. Defaults to `PROMPTLAYER_API_KEY`. */
  apiKey?: string;
  /**
   * When true, configures OpenTelemetry tracing export to PromptLayer.
   * @see https://docs.promptlayer.com/features/observability/traces/auto-instrumentation/overview
   */
  enableTracing?: boolean;
  workspaceId?: number;
  /**
   * When true (default), many API failures throw. When false, methods often
   * return `null`, `false`, or empty fallbacks instead.
   * @see https://docs.promptlayer.com/sdks/javascript#error-handling
   */
  throwOnError?: boolean;
  /** Overrides the PromptLayer API base URL. Defaults to `PROMPTLAYER_BASE_URL` or `https://api.promptlayer.com`. */
  baseURL?: string;
  /**
   * When > 0, enables in-memory TTL caching of prompt templates.
   * Templates are fetched unrendered and substituted locally, reducing
   * API calls. Default: 0 (disabled).
   * @see https://docs.promptlayer.com/sdks/javascript#sdk-cache
   */
  cacheTtlSeconds?: number;
}

const isWorkflowResultsDict = (obj: any): boolean => {
  if (!obj || typeof obj !== "object" || Array.isArray(obj)) {
    return false;
  }

  const REQUIRED_KEYS = [
    "status",
    "value",
    "error_message",
    "raw_error_message",
    "is_output_node",
  ];
  const values = Object.values(obj);

  return values.every((val) => {
    if (typeof val !== "object" || val === null) return false;
    return REQUIRED_KEYS.every((key) => key in val);
  });
};

/**
 * Official PromptLayer JavaScript client.
 *
 * Start with {@link PromptLayer.run} for registry prompts or
 * {@link PromptLayer.templates} to fetch and render templates. For agent
 * tooling, use the docs at https://docs.promptlayer.com/sdks/javascript and
 * https://docs.promptlayer.com/llms.txt rather than scanning package internals.
 *
 * @example
 * ```ts
 * const pl = new PromptLayer({ apiKey: process.env.PROMPTLAYER_API_KEY });
 * const result = await pl.run({
 *   promptName: "support-reply",
 *   inputVariables: { customer_name: "Ada" },
 * });
 * ```
 *
 * @see https://docs.promptlayer.com/sdks/javascript
 * @see https://docs.promptlayer.com/llms.txt
 */
export class PromptLayer {
  apiKey: string;
  baseURL: string;
  /**
   * Prompt template retrieval, listing, publishing, and cache invalidation.
   * @see https://docs.promptlayer.com/features/prompt-registry/overview
   */
  templates: TemplateManager;
  /**
   * Skill collection pull, publish, and update operations.
   * @see https://docs.promptlayer.com/features/skill-collections/overview
   */
  skills: SkillManager;
  /**
   * Tables API for datasets and evaluation sheets.
   * @see https://docs.promptlayer.com/features/tables/overview
   */
  tables: TableManager;
  /**
   * SDK eval runners and related helpers.
   * @see https://docs.promptlayer.com/sdks/evals/overview
   */
  evals: EvalManager;
  /**
   * Group creation for organizing related requests.
   * @see https://docs.promptlayer.com/features/observability/request-logs/request-ids
   */
  group: GroupManager;
  /**
   * Request annotation utilities for metadata, prompt linkage, scores, and groups.
   * @see https://docs.promptlayer.com/features/observability/request-logs/metadata
   */
  track: TrackManager;
  enableTracing: boolean;
  throwOnError: boolean;
  tracerProvider: NodeTracerProvider | null;
  /**
   * Wrap a function in a PromptLayer span when tracing is enabled.
   * @see https://docs.promptlayer.com/features/observability/traces/manual-tracing
   */
  wrapWithSpan: typeof wrapWithSpan;
  /**
   * Trace a tool-style function with a named span.
   * @see https://docs.promptlayer.com/features/observability/traces/manual-tracing
   */
  traceTool: typeof traceTool;

  constructor({
    apiKey = readEnv("PROMPTLAYER_API_KEY"),
    baseURL = readEnv("PROMPTLAYER_BASE_URL"),
    enableTracing = false,
    throwOnError = true,
    cacheTtlSeconds = 0,
  }: ClientOptions = {}) {
    if (apiKey === undefined) {
      throw new Error(
        "PromptLayer API key not provided. Please set the PROMPTLAYER_API_KEY environment variable or pass the api_key parameter."
      );
    }

    this.apiKey = apiKey;
    this.baseURL = baseURL || "https://api.promptlayer.com";
    this.enableTracing = enableTracing;
    this.throwOnError = throwOnError;
    this.tracerProvider = null;
    const cache = cacheTtlSeconds > 0 ? new PromptTemplateCache(cacheTtlSeconds) : null;
    this.templates = new TemplateManager(
      apiKey,
      this.baseURL,
      this.throwOnError,
      cache
    );
    this.skills = new SkillManager(apiKey, this.baseURL, this.throwOnError);
    this.tables = new TableManager(
      apiKey,
      this.baseURL,
      this.throwOnError
    );
    this.group = new GroupManager(apiKey, this.baseURL, this.throwOnError);
    this.track = new TrackManager(apiKey, this.baseURL, this.throwOnError);
    this.wrapWithSpan = wrapWithSpan;
    this.traceTool = traceTool;

    if (enableTracing) {
      this.tracerProvider = setupTracing(enableTracing, apiKey, this.baseURL);
    }
    this.evals = new EvalManager(
      apiKey,
      this.baseURL,
      this.throwOnError,
      this.tracerProvider
    );
  }

  /**
   * Clear cached prompt templates. Pass a name to invalidate one entry, or omit
   * to clear the entire template cache.
   * @see https://docs.promptlayer.com/sdks/javascript#sdk-cache
   */
  invalidate(promptName?: string): void {
    this.templates.invalidate(promptName);
  }

  /**
   * Anthropic SDK proxy that logs requests to PromptLayer.
   * Requires the `@anthropic-ai/sdk` package.
   * @see https://docs.promptlayer.com/sdks/javascript
   */
  get Anthropic() {
    try {
      const module =
        requireProviderSDK("@anthropic-ai/sdk").default;
      return promptLayerBase(
        this.apiKey,
        this.baseURL,
        module,
        "anthropic",
        "anthropic"
      );
    } catch (e) {
      console.error(
        "To use the Anthropic module, you must install the @anthropic-ai/sdk package."
      );
    }
  }

  /**
   * OpenAI SDK proxy that logs requests to PromptLayer.
   * Requires the `openai` package.
   * @see https://docs.promptlayer.com/sdks/javascript
   */
  get OpenAI() {
    try {
      const module = requireProviderSDK("openai").default;
      return promptLayerBase(
        this.apiKey,
        this.baseURL,
        module,
        "openai",
        "openai"
      );
    } catch (e) {
      console.error(
        "To use the OpenAI module, you must install the openai package."
      );
    }
  }

  /**
   * Fetch a prompt from the Prompt Registry and run it with the configured provider.
   * This is the recommended high-level entry point for most integrations.
   *
   * @see https://docs.promptlayer.com/sdks/javascript#using-the-run-method-recommended
   */
  async run({
    promptName,
    promptVersion,
    promptReleaseLabel,
    inputVariables,
    tags,
    metadata,
    groupId,
    modelParameterOverrides,
    stream = false,
    provider,
    model,
    skipLogging = false,
  }: RunRequest) {
    const tracer = getTracer();

    return tracer.startActiveSpan("PromptLayer Run", async (span) => {
      let spanOwnershipTransferred = false;
      try {
        span.setAttributes(
          runSpanAttributes(
            promptName,
            promptVersion,
            promptReleaseLabel,
            metadata,
            SDK_VERSION
          )
        );

        const prompt_input_variables = inputVariables;
        const templateGetParams: GetPromptTemplateParams = {
          label: promptReleaseLabel,
          version: promptVersion,
          metadata_filters: metadata,
          provider,
          model,
          model_parameter_overrides: modelParameterOverrides,
        };
        if (inputVariables) templateGetParams.input_variables = inputVariables;

        const fetchAttributes: opentelemetry.Attributes = {
          node_type: "PROMPT_TEMPLATE",
          prompt_name: promptName,
          "promptlayer.prompt.name": promptName,
          "promptlayer.prompt.requested.name": promptName,
        };
        if (promptVersion !== undefined) {
          fetchAttributes["promptlayer.prompt.requested.version"] =
            String(promptVersion);
        }
        if (promptReleaseLabel !== undefined) {
          fetchAttributes["promptlayer.prompt.requested.label"] =
            promptReleaseLabel;
        }
        const promptBlueprint = await tracer.startActiveSpan(
          "Prompt template fetch",
          {
            attributes: fetchAttributes,
            kind: opentelemetry.SpanKind.INTERNAL,
          },
          async (fetchSpan) => {
            try {
              const blueprint = await this.templates.get(
                promptName,
                templateGetParams
              );
              if (!blueprint) {
                throw new Error(
                  `Cannot proceed: prompt template '${promptName}' could not be fetched. ` +
                  `Check the warnings above for the actual error.`
                );
              }
              fetchSpan.setAttributes({
                "promptlayer.prompt.id": String(blueprint.id),
                "promptlayer.prompt.version": String(
                  blueprint.version
                ),
              });
              return blueprint;
            } catch (error) {
              recordSpanError(fetchSpan, error);
              throw error;
            } finally {
              fetchSpan.end();
            }
          }
        );

        const promptAttributes: opentelemetry.Attributes = {
          "promptlayer.prompt.name": promptName,
          "promptlayer.prompt.id": String(promptBlueprint.id),
          "promptlayer.prompt.version": String(
            promptBlueprint.version
          ),
        };
        if (promptReleaseLabel) {
          promptAttributes["promptlayer.prompt.label"] =
            promptReleaseLabel;
        }
        span.setAttributes(promptAttributes);

        const promptTemplate = promptBlueprint.prompt_template;
        if (!promptBlueprint!.llm_kwargs) {
          const errorMessage = `Prompt '${promptName}' does not have any LLM kwargs associated with it. Please set your model parameters in the registry in the PromptLayer dashboard.`;
          if (this.throwOnError) {
            throw new Error(errorMessage);
          } else {
            console.warn(`WARNING: ${errorMessage}`);
          }
        }

        const promptBlueprintMetadata = promptBlueprint!.metadata;
        if (!promptBlueprintMetadata) {
          throw new Error(
            `Prompt '${promptName}' does not have any metadata associated with it.`
          );
        }

        const promptBlueprintModel = promptBlueprintMetadata.model;
        if (!promptBlueprintModel) {
          throw new Error(
            `Prompt '${promptName}' does not have a model parameters associated with it.`
          );
        }

        const customProvider = promptBlueprint!.custom_provider;
        const request_start_time = new Date().toISOString();

        const { provider_type, kwargs } = configureProviderSettings(
          promptBlueprint,
          customProvider,
          modelParameterOverrides,
          stream
        );

        let provider_type_config = provider_type;
        if (provider_type === "openai" || provider_type === "openai.azure") {
          const api_type = promptBlueprintModel.api_type;
          provider_type_config = `${provider_type}:${api_type}`;
        } else if (provider_type === "openrouter") {
          const api_type = promptBlueprintModel.api_type;
          provider_type_config =
            api_type === "images" ||
            api_type === "video" ||
            api_type === "speech"
              ? `openrouter:${api_type}`
              : "openrouter:chat";
        }

        if (promptBlueprintModel.name.startsWith("gemini")) {
          provider_type_config = "google";
        } else if (promptBlueprintModel.name.startsWith("claude")) {
          provider_type_config = "anthropic";
        }

        const config = getProviderConfig(provider_type_config, promptTemplate);
        const { function_name, stream_function } = config;

        const request_function = MAP_PROVIDER_TO_FUNCTION[provider_type];
        if (!request_function) {
          throw new Error(
            `No request function found for provider: ${provider_type}`
          );
        }

        const _trackRequest = (body: object) => {
          if (skipLogging) {
            return Promise.resolve({ request_id: null, prompt_blueprint: null });
          }
          const request_end_time = new Date().toISOString();
          return trackRequest(
            this.baseURL,
            {
              function_name,
              provider_type,
              args: [],
              kwargs,
              tags,
              request_start_time,
              request_end_time,
              api_key: this.apiKey,
              metadata,
              prompt_id: promptBlueprint!.id,
              prompt_version: promptBlueprint!.version,
              prompt_input_variables,
              group_id: groupId,
              return_prompt_blueprint: true,
              span_id: span.spanContext().spanId,
              ...body,
            },
            this.throwOnError
          );
        };

        let response: any;
        try {
          const invokeProvider = () =>
            request_function(promptBlueprint, kwargs);
          response = await withPromptLayerProviderRequestContext(
            {
              promptAttributes,
              requestLogSpanId: span.spanContext().spanId,
            },
            invokeProvider
          );
        } catch (llmError: unknown) {
          const errorType = categorizeError(llmError);
          const errorMessage =
            llmError instanceof Error ? llmError.message : String(llmError);
          await _trackRequest({
            request_response: {},
            status: "ERROR",
            error_type: errorType,
            error_message: errorMessage,
          });
          throw llmError;
        }

        if (stream) {
          const streamIterator = streamResponse(
            response,
            _trackRequest,
            stream_function,
            metadata || promptBlueprint!.metadata
          );
          spanOwnershipTransferred = true;
          return (async function* () {
            try {
              for await (const chunk of streamIterator) {
                yield chunk;
              }
            } catch (error) {
              recordSpanError(span, error);
              throw error;
            } finally {
              span.end();
            }
          })();
        }
        const requestLog = await _trackRequest({ request_response: response });

        const functionOutput = {
          request_id: requestLog.request_id,
          raw_response: response,
          prompt_blueprint: requestLog.prompt_blueprint,
        };

        return functionOutput;
      } catch (error) {
        recordSpanError(span, error);
        throw error;
      } finally {
        if (!spanOwnershipTransferred) {
          span.end();
        }
      }
    });
  }

  /**
   * Execute a PromptLayer workflow by name, optionally pinning a label or version.
   *
   * @see https://docs.promptlayer.com/sdks/javascript#running-workflows
   */
  async runWorkflow({
    workflowName,
    inputVariables = {},
    metadata = {},
    workflowLabelName = null,
    workflowVersion = null, // This is the version number, not the version ID
    returnAllOutputs = false,
  }: WorkflowRequest): Promise<WorkflowResponse> {
    try {
      const result = await runWorkflowRequest({
        workflow_name: workflowName,
        input_variables: inputVariables,
        metadata,
        workflow_label_name: workflowLabelName,
        workflow_version_number: workflowVersion,
        return_all_outputs: returnAllOutputs,
        api_key: this.apiKey,
        baseURL: this.baseURL,
      });

      if (!returnAllOutputs) {
        if (isWorkflowResultsDict(result)) {
          const nodeValues = Object.values(result);

          const outputNodes = nodeValues.filter(
            (node: any) => node.is_output_node === true
          );

          if (outputNodes.length === 0) {
            throw new Error(JSON.stringify(result, null, 2));
          }

          const anyOutputSuccess = outputNodes.some(
            (node: any) => node.status === "SUCCESS"
          );
          if (!anyOutputSuccess) {
            throw new Error(JSON.stringify(result, null, 2));
          }
        }
      }

      return result;
    } catch (error) {
      if (error instanceof Error) {
        console.error("Error running workflow:", error.message);
        throw new Error(`Error running workflow: ${error.message}`);
      } else {
        console.error("Unknown error running workflow:", error);
        throw new Error("Unknown error running workflow");
      }
    }
  }

  /**
   * Manually log a request to PromptLayer when you are not using a provider proxy
   * or {@link PromptLayer.run}.
   *
   * @see https://docs.promptlayer.com/features/observability/request-logs/custom-logging
   */
  async logRequest(body: LogRequest) {
    return utilLogRequest(this.apiKey, this.baseURL, body, this.throwOnError);
  }
}

